import datetime,hashlib,importlib.util,json,statistics,sys
from pathlib import Path
root=Path('/home/phil/dev/war_next'); sys.path.insert(0,str(root/'scripts'))
spec=importlib.util.spec_from_file_location('war_stability',root/'scripts/stability.py'); stability=importlib.util.module_from_spec(spec);spec.loader.exec_module(stability)
sha=lambda p:hashlib.sha256(Path(p).read_bytes()).hexdigest()
control=root/'artifacts/baselines/241a172/war-relay'; selected=root/'artifacts/candidates/registry-retirement/war-relay'; client=root/'artifacts/baselines/241a172/stress'
record={'timestamp_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'server_sha256':{'control':sha(control),'selected':sha(selected)},'client_sha256':sha(client),'runner_sha256':sha(root/'scripts/stability.py'),'comparison_source':Path(__file__).read_text(),'notes':'Sequential fresh four-worker relay on CPUs 0-3, frozen verified stress client on 4-7. Three alternating pairs per mode/payload, four seconds per case, 64 clients. Incoming rates disabled by the runner; other settings are in each command. CPU includes setup and teardown. Churn verifies normal Close; traffic intentionally drops 64 socket handles and accounts for every read/write departure. Finite loopback cost guard, no TLS/capacity guarantee.','cases':[]}
output=root/'docs/benchmarks/2026-10-16-registry-cost.json'
for mode,payload in [('traffic',1024),('traffic',65536),('churn',8)]:
 for repetition in range(1,4):
  arms=[('control',control),('selected',selected)]
  if repetition==2: arms.reverse()
  for label,server in arms:
   case=stability.run_case(mode,4,64,server_binary=server,stress_binary=client,server_cpus='0-3',client_cpus='4-7',payload_bytes=payload)
   metrics={k:int(float(v)) for k,v in case['final']['metrics'].items()}
   result=next(v for v in case['output'] if v.get('event')=='result')
   error_keys=['war_handshake_errors_total','war_origin_rejected_total','war_join_rejected_total','war_rejected_total','war_protocol_errors_total','war_close_failures_total','war_write_timeouts_total','war_aborted_writes_total','war_global_pressure_total','war_slow_consumers_total','war_rate_limited_total','war_read_buffer_reservations_rejected_total']
   case['zero_error_checks']={k:metrics[k]==0 for k in error_keys}
   case['resource_checks']={k:metrics[k]==0 for k in ['war_connections','war_sessions','war_queued_bytes','war_variable_bytes','war_read_buffer_reserved_bytes']}
   case['resource_checks']['war_channels']=metrics['war_channels']==1
   departures=metrics['war_transport_disconnects_total']+metrics['war_write_errors_total']
   case.update(label=label,repetition=repetition,payload_bytes=payload,server_sha256=sha(server),copied_bytes=metrics['war_routing_copied_bytes_total'],expected_tcp_departures=64 if mode=='traffic' else 0,observed_tcp_departures=departures)
   case['counts_exact']=metrics['war_accepted_total']==metrics['war_joined_total']==metrics['war_disconnected_total']==result['joins']
   case['server_cpu_seconds']=case['final']['process']['cpu_seconds']-case['baseline']['process']['cpu_seconds']
   case['cpu_ns_per_verified']=case['server_cpu_seconds']*1e9/result['verified_deliveries']
   case['passed']=case['passed'] and all(case['resource_checks'].values()) and all(case['zero_error_checks'].values()) and case['counts_exact'] and departures==case['expected_tcp_departures'] and case['copied_bytes']==0
   record['cases'].append(case);output.write_text(json.dumps(record,indent=2)+'\n')
   assert case['passed'],(mode,payload,label,repetition)
record['medians']={}
for mode,payload in [('traffic',1024),('traffic',65536),('churn',8)]:
 for label in ['control','selected']:
  cases=[c for c in record['cases'] if c['label']==label and c['mode']==mode and c['payload_bytes']==payload]
  results=[next(v for v in c['output'] if v.get('event')=='result') for c in cases]
  record['medians'][f'{mode}/{payload}/{label}']={'verified_per_second':statistics.median(r['deliveries_per_second'] for r in results),'cpu_ns_per_verified':statistics.median(c['cpu_ns_per_verified'] for c in cases),'p99_upper_ms':statistics.median(r['latency_p99_upper_ms'] for r in results),'throughput_range':[min(r['deliveries_per_second'] for r in results),max(r['deliveries_per_second'] for r in results)]}
record['passed']=True;output.write_text(json.dumps(record,indent=2)+'\n');print(json.dumps({'passed':True,'medians':record['medians']}),flush=True)
